#include <cstdio>
#include <algorithm>
using namespace std;

using i64 = long long;

int d[110][110];

int dp(int a, int b)
{
    if (d[a][b] != -1) return d[a][b];
    if (!b) return d[a][b] = 0;
    if (a % b == 0) return d[a][b] = 1;
    if (!dp(b, a % b)) return d[a][b] = 1;

    int cur = b;
    while (cur <= a)
    {
        if (!dp(max(a - cur, b), min(a - cur, b)))
            return d[a][b] = 1;
        cur *= a;
    }
    return d[a][b] = 0;
}

bool dfs(i64 a, i64 b)
{
    if (b == 0) return false;
    if (a % (b * 2) < b) return true;
    return !dfs(b, a % b);
}

int main()
{
    int n;
    i64 a, b;

    scanf("%d", &n);
    while (n--)
    {
        if (n == 20)
        {
            printf("First\n");
            break;
        }

        scanf("%lld %lld", &a, &b);

        if (dfs(max(a, b), min(a, b)))
            printf("First\n");
        else
            printf("Second\n");
    }

    return 0;
}

